// Writes aish.koplugin/aishlib/wordlist.lua from the extension's list: node koreader/tests/gen-wordlist.mjs (from the repo root)
import { WORDS } from '../../plugin/src/modules/syncWordlist.js';
import fs from 'fs';
if (WORDS.length !== 2048) throw new Error('expected 2048 words');
fs.writeFileSync(new URL('../aish.koplugin/aishlib/wordlist.lua', import.meta.url),
  '-- The 2,048 words of the BIP-39 English list (MIT), the same list the extension suggests passphrases from (syncWordlist.js).\n' +
  '-- Generated by koreader/tests/gen-wordlist.mjs; checked against the sha256 in sync-vector.json.\nreturn [[\n' + WORDS.join('\n') + '\n]]\n');
